import{_ as r,C as n,o,c as i,j as e,a as d,E as s,a2 as l}from"./chunks/framework.BSl-aDiU.js";const k=JSON.parse('{"title":"4. Levels & balance","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/levels.md","filePath":"gdd/levels.md"}'),h={name:"gdd/levels.md"},p={id:"_4-1-balance-rule-balance-rule",tabindex:"-1"},c={id:"_4-2-level-checker-checker",tabindex:"-1"},u={id:"_4-3-shipped-levels",tabindex:"-1"};function g(m,t,b,v,f,y){const a=n("Badge");return o(),i("div",null,[t[9]||(t[9]=e("h1",{id:"_4-levels-balance",tabindex:"-1"},[d("4. Levels & balance "),e("a",{class:"header-anchor",href:"#_4-levels-balance","aria-label":'Permalink to "4. Levels & balance"'},"​")],-1)),e("h2",p,[t[0]||(t[0]=d("4.1 Balance rule {#balance-rule} ",-1)),s(a,{type:"tip",text:"Live"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#_4-1-balance-rule-balance-rule","aria-label":'Permalink to "4.1 Balance rule {#balance-rule} <Badge type="tip" text="Live" />"'},"​",-1))]),t[10]||(t[10]=l('<blockquote><p>For every colour, the <strong>total ammo of that colour&#39;s fighters</strong> must equal the <strong>total hit points of that colour&#39;s enemies and boss parts</strong> across all stages.</p></blockquote><p>With the default 18 ammo per fighter, each colour&#39;s enemies add up to a multiple of 18. Handy combinations for one 18-ammo fighter:</p><table tabindex="0"><thead><tr><th>Enemies</th><th>Hit points</th></tr></thead><tbody><tr><td>2 large</td><td>9 + 9</td></tr><tr><td>3 medium</td><td>6 + 6 + 6</td></tr><tr><td>6 small</td><td>3 × 6</td></tr><tr><td>1 large + 1 medium + 1 small</td><td>9 + 6 + 3</td></tr><tr><td>2 medium + 2 small</td><td>6 + 6 + 3 + 3</td></tr><tr><td>A boss part</td><td>18 or 36</td></tr></tbody></table><p>Balance makes a level <em>possible</em> but not <em>easy</em>: the order of taps still decides whether the 5-slot flight zone jams.</p>',4)),e("h2",c,[t[3]||(t[3]=d("4.2 Level checker {#checker} ",-1)),s(a,{type:"tip",text:"Live"}),t[4]||(t[4]=d()),t[5]||(t[5]=e("a",{class:"header-anchor",href:"#_4-2-level-checker-checker","aria-label":'Permalink to "4.2 Level checker {#checker} <Badge type="tip" text="Live" />"'},"​",-1))]),t[11]||(t[11]=l("<p><code>npm run validate:levels</code> (it also runs at the start of every <code>npm run build</code>) checks each <code>src/levels/level-*.json</code>:</p><ol><li><strong>Well formed</strong>: known cell letters, every stage fits on screen, every stage has enemies, a boss (2–8 parts) only in the last stage, <code>hpPerEnemy</code> between 20 and 40.</li><li><strong>Compact, full hangar</strong>: no empty cells, rows and columns differ by at most 1, fewer walls than the shorter side (elevators don&#39;t count as walls). Every elevator faces a fighter cell, has a queue, and no two face the same cell. Mystery and frozen entries point at fighter cells and never overlap.</li><li><strong>Balanced</strong>: ammo equals hit points for every colour.</li><li><strong>Winnable</strong>: a solver searches tap orders, modelling a patient player who lets the flight zone finish shooting before each tap. It uses the game&#39;s own stage layout, so it respects shielding (front targets first), target order, the oldest-first ammo rule, elevator refills and frozen counters (it knows mystery colours). The build fails if no winning order exists. The solver doesn&#39;t model time, so it can&#39;t see flight-zone HP; that is tuned by playtesting (see 4.4).</li><li><strong>Difficulty signal</strong>: the <em>random win rate</em> is the share of 2,000 games of random legal taps that win. Lower means harder. It varies by about ±1 point between runs.</li></ol><p><code>node scripts/validate-levels.ts --solution</code> also prints a winning tap order (row,col) for each level.</p>",3)),e("h2",u,[t[6]||(t[6]=d("4.3 Shipped levels ",-1)),s(a,{type:"tip",text:"Live"}),t[7]||(t[7]=d()),t[8]||(t[8]=e("a",{class:"header-anchor",href:"#_4-3-shipped-levels","aria-label":'Permalink to "4.3 Shipped levels <Badge type="tip" text="Live" />"'},"​",-1))]),t[12]||(t[12]=l(`<p>Legend: <code>#</code> wall · <code>^</code> <code>v</code> <code>&lt;</code> <code>&gt;</code> elevator facing up / down / left / right · letters are fighters (<strong>R</strong>ed <strong>B</strong>lue <strong>G</strong>reen <strong>Y</strong>ellow <strong>P</strong>urple <strong>O</strong>range <strong>C</strong>yan <strong>K</strong> pink). The top row touches the flight zone and is the only row that can launch at the start.</p><table tabindex="0"><thead><tr><th>#</th><th>Name</th><th>Grid (cols × rows)</th><th>Fighters</th><th>Colours</th><th>Stages</th><th>hpPerEnemy</th><th>Zone HP</th><th>Random win rate</th></tr></thead><tbody><tr><td>1</td><td>First Flight</td><td>2 × 2</td><td>4</td><td>2</td><td>2</td><td>40</td><td>480 (12 enemies)</td><td>100%</td></tr><tr><td>2</td><td>Wall Drills</td><td>3 × 3, 1 wall</td><td>8</td><td>3</td><td>3</td><td>35</td><td>770 (22)</td><td>~90%</td></tr><tr><td>3</td><td>Boss Debut</td><td>4 × 3</td><td>12</td><td>4</td><td>3 (boss)</td><td>30</td><td>750 (15 + boss)</td><td>~57%</td></tr><tr><td>4</td><td>Crossfire</td><td>5 × 4</td><td>20</td><td>6</td><td>4 (boss)</td><td>25</td><td>1075 (33 + boss)</td><td>~23%</td></tr><tr><td>5</td><td>Armada</td><td>6 × 6, 4 walls</td><td>32</td><td>8</td><td>5 (boss)</td><td>20</td><td>1640 (47 + boss, +500 bonus)</td><td>under 1%</td></tr><tr><td>6</td><td>Reinforcements</td><td>3 × 3, 1 wall, 1 elevator</td><td>9</td><td>2</td><td>2</td><td>40</td><td>1280 (32)</td><td>100% (tutorial)</td></tr><tr><td>7</td><td>Supply Line</td><td>4 × 4, 1 wall, 1 elevator</td><td>17</td><td>3</td><td>3 (boss)</td><td>35</td><td>1785 (41 + boss)</td><td>~77%</td></tr><tr><td>8</td><td>Double Lift</td><td>4 × 4, 2 elevators</td><td>19</td><td>4</td><td>4 (boss)</td><td>30</td><td>1470 (39 + boss)</td><td>~57%</td></tr><tr><td>9</td><td>Rush Hour</td><td>5 × 5, 1 wall, 2 elevators</td><td>28</td><td>5</td><td>5 (boss)</td><td>25</td><td>1725 (59 + boss)</td><td>~27%</td></tr><tr><td>10</td><td>Endless Hangar</td><td>6 × 5, 1 wall, 3 elevators</td><td>36</td><td>8</td><td>6 (boss)</td><td>20</td><td>1560 (68 + boss)</td><td>~0% (solver-proven winnable)</td></tr></tbody></table><p>Levels 6–10 start a second difficulty ramp around the elevator: level 6 is a tutorial, 7 and 8 step up moderately, 9 and 10 are hard. Fighter counts include the ones waiting in elevators.</p><h3 id="levels-11–35" tabindex="-1">Levels 11–35 <a class="header-anchor" href="#levels-11–35" aria-label="Permalink to &quot;Levels 11–35&quot;">​</a></h3><p>Each block opens easy and ends hard; a new obstacle starts its block with a tutorial level.</p><table tabindex="0"><thead><tr><th>Levels</th><th>Theme</th></tr></thead><tbody><tr><td>11–15</td><td>Mystery fighters (11 is the tutorial)</td></tr><tr><td>16–20</td><td>Mystery + elevators</td></tr><tr><td>21–25</td><td>Frozen fighters (21 is the tutorial)</td></tr><tr><td>26–35</td><td>Two obstacles each; <strong>30 and 35 use all three</strong> and are the peaks</td></tr></tbody></table><table tabindex="0"><thead><tr><th>#</th><th>Name</th><th>Grid (cols × rows)</th><th>Fighters</th><th>Colours</th><th>Obstacles</th><th>Stages</th><th>hpPerEnemy</th><th>Random win rate</th></tr></thead><tbody><tr><td>11</td><td>Fog of War (tutorial)</td><td>3 × 3</td><td>9</td><td>2</td><td>3 mystery</td><td>2</td><td>40</td><td>100%</td></tr><tr><td>12</td><td>Blind Spot</td><td>4 × 4, 1 wall</td><td>15</td><td>3</td><td>4 mystery</td><td>4 (boss: Shade Hawk, raptor)</td><td>35</td><td>~81%</td></tr><tr><td>13</td><td>Masquerade</td><td>4 × 4</td><td>16</td><td>4</td><td>6 mystery</td><td>3 (boss: Veil Mantis, mantis)</td><td>30</td><td>~49%</td></tr><tr><td>14</td><td>Smoke Screen</td><td>5 × 5, 1 wall</td><td>24</td><td>5</td><td>8 mystery</td><td>4 (boss: Eclipse Ring, dreadnought)</td><td>25</td><td>~20%</td></tr><tr><td>15</td><td>Dark Hangar</td><td>6 × 6, 2 walls</td><td>34</td><td>7</td><td>12 mystery</td><td>6 (boss: Night Raptor, raptor)</td><td>20</td><td>under 1%</td></tr><tr><td>16</td><td>Hidden Supply</td><td>4 × 4</td><td>18</td><td>3</td><td>1 elevator, 3 mystery</td><td>4 (boss: Hive Warden, mantis)</td><td>40</td><td>~88%</td></tr><tr><td>17</td><td>Shadow Lift</td><td>4 × 4, 1 wall</td><td>17</td><td>4</td><td>1 elevator, 4 mystery</td><td>3 (boss: Gloom Saucer, dreadnought)</td><td>35</td><td>~64%</td></tr><tr><td>18</td><td>Smoke and Mirrors</td><td>5 × 4</td><td>24</td><td>4</td><td>2 elevators, 5 mystery</td><td>5 (boss: Mirage, raptor)</td><td>30</td><td>~38%</td></tr><tr><td>19</td><td>Ghost Convoy</td><td>5 × 5, 1 wall</td><td>29</td><td>5</td><td>2 elevators, 7 mystery</td><td>6 (boss: Phantom Queen, mantis)</td><td>25</td><td>~13%</td></tr><tr><td>20</td><td>Blackout</td><td>6 × 6, 2 walls</td><td>41</td><td>8</td><td>3 elevators, 10 mystery</td><td>7 (boss: Black Star, dreadnought)</td><td>20</td><td>~0%</td></tr><tr><td>21</td><td>Cold Start (tutorial)</td><td>3 × 3</td><td>9</td><td>2</td><td>frozen 3</td><td>2</td><td>40</td><td>100%</td></tr><tr><td>22</td><td>Permafrost</td><td>4 × 4</td><td>16</td><td>3</td><td>frozen 3/4</td><td>3 (boss: Frost Talon, raptor)</td><td>35</td><td>~75%</td></tr><tr><td>23</td><td>Ice Field</td><td>4 × 4, 1 wall</td><td>15</td><td>4</td><td>frozen 2/4/5</td><td>3 (boss: Rime Mantis, mantis)</td><td>30</td><td>~53%</td></tr><tr><td>24</td><td>Deep Freeze</td><td>5 × 5, 1 wall</td><td>24</td><td>5</td><td>frozen 3/5/6</td><td>4 (boss: Glacier, dreadnought)</td><td>25</td><td>~19%</td></tr><tr><td>25</td><td>Absolute Zero</td><td>6 × 6, 2 walls</td><td>34</td><td>7</td><td>frozen 3/4/6/8</td><td>6 (boss: Zero Point, raptor)</td><td>20</td><td>~0%</td></tr><tr><td>26</td><td>Frost Fog</td><td>4 × 4</td><td>16</td><td>4</td><td>4 mystery, frozen 3/5</td><td>3 (boss: Hoarfrost, mantis)</td><td>35</td><td>~63%</td></tr><tr><td>27</td><td>Cold Storage</td><td>4 × 4, 1 wall</td><td>17</td><td>4</td><td>1 elevator, frozen 3/4</td><td>4 (boss: Cryo Vault, dreadnought)</td><td>35</td><td>~48%</td></tr><tr><td>28</td><td>Night Shift</td><td>5 × 4</td><td>24</td><td>4</td><td>2 elevators, 5 mystery</td><td>5 (boss: Nightwing, raptor)</td><td>30</td><td>~31%</td></tr><tr><td>29</td><td>Ice Lift</td><td>5 × 5, 1 wall</td><td>29</td><td>4</td><td>2 elevators, frozen 4/6</td><td>6 (boss: Frost Hive, mantis)</td><td>30</td><td>~22%</td></tr><tr><td>30</td><td>Triple Threat</td><td>5 × 5</td><td>29</td><td>5</td><td>2 elevators, 5 mystery, frozen 3/5</td><td>5 (boss: Tri-Core, dreadnought)</td><td>25</td><td>~10%</td></tr><tr><td>31</td><td>Glacier Lift</td><td>5 × 5, 1 wall</td><td>29</td><td>5</td><td>2 elevators, frozen 4/6</td><td>6 (boss: Ice Empress, mantis)</td><td>25</td><td>~15%</td></tr><tr><td>32</td><td>Whiteout</td><td>5 × 5, 1 wall</td><td>24</td><td>6</td><td>7 mystery, frozen 3/4/6</td><td>4 (boss: Blizzard, raptor)</td><td>25</td><td>~8%</td></tr><tr><td>33</td><td>Dark Elevators</td><td>6 × 5, 1 wall</td><td>34</td><td>6</td><td>2 elevators, 8 mystery</td><td>6 (boss: Umbra, dreadnought)</td><td>20</td><td>under 1%</td></tr><tr><td>34</td><td>Frozen Shadows</td><td>6 × 6, 2 walls</td><td>34</td><td>7</td><td>9 mystery, frozen 3/5/7</td><td>6 (boss: Shiver, raptor)</td><td>20</td><td>~0%</td></tr><tr><td>35</td><td>Final Front</td><td>6 × 6, 1 wall</td><td>42</td><td>8</td><td>3 elevators, 8 mystery, frozen 4/6/8</td><td>7 (boss: Omega Swarm, mantis)</td><td>20</td><td>~0%</td></tr></tbody></table><p>These levels were generated by the same search, which also places walls, elevators, mystery and frozen fighters at random and builds each stage from the colour counts. Random win rates of ~0% mean random tapping never won in 2,000 tries; the solver still proves each one winnable. Full layouts are in <code>src/levels/level-NN.json</code>.</p><p>The grids were found by a search that shuffles each level&#39;s fighters into the compact grid (and, for levels 6–10, into the elevator queues, with stages built from the colour counts), keeps only layouts the solver can win, and picks the one whose random win rate is closest to that level&#39;s difficulty target.</p><h3 id="level-1-first-flight" tabindex="-1">Level 1: First Flight <a class="header-anchor" href="#level-1-first-flight" aria-label="Permalink to &quot;Level 1: First Flight&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RB</span></span>
<span class="line"><span>BR</span></span></code></pre></div><p>Teaches tapping: the back row can only launch once the front row has gone. Never more than 4 fighters, so the flight zone can&#39;t jam.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies (back row first)</th></tr></thead><tbody><tr><td>1</td><td>Red: 3 small + 1 large · Blue: 3 medium</td></tr><tr><td>2</td><td>Red: 3 medium · Blue: 2 large</td></tr></tbody></table><h3 id="level-2-wall-drills" tabindex="-1">Level 2: Wall Drills <a class="header-anchor" href="#level-2-wall-drills" aria-label="Permalink to &quot;Level 2: Wall Drills&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GBG</span></span>
<span class="line"><span>RBR</span></span>
<span class="line"><span>BR#</span></span></code></pre></div><p>Stage 1 wants only red, but the top row is green and blue. Digging through it takes slots, and launching too many blues and greens early can fill the zone.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies</th></tr></thead><tbody><tr><td>1</td><td>Red: 2 large + 3 medium (36)</td></tr><tr><td>2</td><td>Green: 2 large + 3 medium (36) · Blue: 3 small + 1 large (18)</td></tr><tr><td>3</td><td>Red: large + medium + small (18) · Blue: 3 medium + 2 large (36)</td></tr></tbody></table><h3 id="level-3-boss-debut" tabindex="-1">Level 3: Boss Debut <a class="header-anchor" href="#level-3-boss-debut" aria-label="Permalink to &quot;Level 3: Boss Debut&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GRYY</span></span>
<span class="line"><span>BRGR</span></span>
<span class="line"><span>YBBG</span></span></code></pre></div><p>The first boss, with 4 parts: the nose (red) shields the core (yellow), so the nose has to fall first.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies</th></tr></thead><tbody><tr><td>1</td><td>Red: 2 large (18) · Blue: 3 medium (18)</td></tr><tr><td>2</td><td>Green: large + medium + small · Yellow: 3 medium · Red: 2 medium + 2 small (18 each)</td></tr><tr><td>3</td><td><strong>Boss &quot;Iron Hawk&quot;</strong>: wings Blue 36 and Green 36 · core Yellow 36 · nose Red 18</td></tr></tbody></table><h3 id="level-4-crossfire" tabindex="-1">Level 4: Crossfire <a class="header-anchor" href="#level-4-crossfire" aria-label="Permalink to &quot;Level 4: Crossfire&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RROGB</span></span>
<span class="line"><span>OBYPG</span></span>
<span class="line"><span>PGYRY</span></span>
<span class="line"><span>PBBRO</span></span></code></pre></div><p>Six colours in a full 5 × 4 hangar. Stages 2 and 3 stack two or three rows of enemies, so front rows of the wrong colour hold back the colours behind them.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies</th></tr></thead><tbody><tr><td>1</td><td>Red: 2 large · Blue: 3 medium · Green: large + medium + small (18 each)</td></tr><tr><td>2</td><td>Yellow: 2 large · Purple: 3 medium · Orange: 6 small · Red: large + medium + small (18 each)</td></tr><tr><td>3</td><td>Blue: 2 large · Green: 3 medium · Yellow: 2 medium + 2 small · Orange: 2 large (18 each)</td></tr><tr><td>4</td><td><strong>Boss &quot;Twin Talon&quot;</strong>: wings Red 36 and Blue 36 · core Green 18 · nose Yellow 18 · engines Purple 36 and Orange 18</td></tr></tbody></table><h3 id="level-5-armada" tabindex="-1">Level 5: Armada <a class="header-anchor" href="#level-5-armada" aria-label="Permalink to &quot;Level 5: Armada&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KCRGBB</span></span>
<span class="line"><span>OY#PPC</span></span>
<span class="line"><span>BOOGP#</span></span>
<span class="line"><span>GC#RRY</span></span>
<span class="line"><span>YRGYK#</span></span>
<span class="line"><span>KCKBPO</span></span></code></pre></div><p>Eight colours, 32 fighters (4 per colour, 72 ammo per colour, 576 in total) and the lowest zone HP per enemy. Random tapping almost never wins.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Enemies</th></tr></thead><tbody><tr><td>1</td><td>Red: 2 large · Blue: 3 medium · Green: 2 large · Yellow: large + medium + small (18 each)</td></tr><tr><td>2</td><td>Purple: 2 large · Orange: 3 medium · Cyan: 2 large · Pink: 2 medium + 2 small (18 each)</td></tr><tr><td>3</td><td>Red · Blue · Orange · Cyan: 2 large each · Purple · Green: 3 medium each (18 each)</td></tr><tr><td>4</td><td>Yellow: 2 large · Pink: 2 large · Red: 3 medium · Blue: large + medium + small · Green: 2 large (18 each)</td></tr><tr><td>5</td><td><strong>Boss &quot;Dread Armada&quot;</strong> (all 8 slots): wings Red 18 and Blue 18 · core Green 18 · nose Yellow 36 · engines Purple 36 and Orange 36 · gun pods Cyan 36 and Pink 36</td></tr></tbody></table><h3 id="level-6-reinforcements-elevator-tutorial" tabindex="-1">Level 6: Reinforcements (elevator tutorial) <a class="header-anchor" href="#level-6-reinforcements-elevator-tutorial" aria-label="Permalink to &quot;Level 6: Reinforcements (elevator tutorial)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RRB</span></span>
<span class="line"><span>RBB</span></span>
<span class="line"><span>#^R      elevator (row 3) holds: R, B</span></span></code></pre></div><p>Two colours, nothing to plan around: the point is to see the elevator refill the middle cell twice. The tutorial overlay explains it before the first stage.</p><h3 id="level-7-supply-line" tabindex="-1">Level 7: Supply Line <a class="header-anchor" href="#level-7-supply-line" aria-label="Permalink to &quot;Level 7: Supply Line&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RBRG</span></span>
<span class="line"><span>GRGB</span></span>
<span class="line"><span>RR^G     elevator holds: R, B, G</span></span>
<span class="line"><span>#BBB</span></span></code></pre></div><p>Three colours and one elevator feeding the middle of the board, so the column above it keeps refilling. Boss: <strong>Mantis Queen</strong> (mantis, 3 parts: Blue 36, Green 36, Red 18).</p><h3 id="level-8-double-lift" tabindex="-1">Level 8: Double Lift <a class="header-anchor" href="#level-8-double-lift" aria-label="Permalink to &quot;Level 8: Double Lift&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GGRR</span></span>
<span class="line"><span>B&gt;YG     elevator (row 2) faces right, holds: Y, R</span></span>
<span class="line"><span>YGYB</span></span>
<span class="line"><span>RB^B     elevator (row 4) faces up, holds: B, R, G</span></span></code></pre></div><p>Two elevators that refill cells the player needs to dig through. Boss: <strong>Razorwing</strong> (raptor, 4 parts: Yellow 18, Red 36, Green 36, Blue 18).</p><h3 id="level-9-rush-hour" tabindex="-1">Level 9: Rush Hour <a class="header-anchor" href="#level-9-rush-hour" aria-label="Permalink to &quot;Level 9: Rush Hour&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>YGPGR</span></span>
<span class="line"><span>B&lt;GBY    elevator faces left, holds: P, R, Y</span></span>
<span class="line"><span>BGBYB</span></span>
<span class="line"><span>PBRvR    elevator faces down, holds: G, Y, R</span></span>
<span class="line"><span>#RPGP</span></span></code></pre></div><p>Five colours, four regular stages with stacked rows, and elevators that refill cells away from the exit. Boss: <strong>Star Bastion</strong> (dreadnought, 5 parts, mostly 36 hp).</p><h3 id="level-10-endless-hangar" tabindex="-1">Level 10: Endless Hangar <a class="header-anchor" href="#level-10-endless-hangar" aria-label="Permalink to &quot;Level 10: Endless Hangar&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PGRKYG</span></span>
<span class="line"><span>O^KP&gt;R   elevators face up (holds R, Y, Y) and right (holds R, Y, G, O)</span></span>
<span class="line"><span>KRBCGP</span></span>
<span class="line"><span>#BC&lt;CK   elevator faces left, holds: O, G, Y</span></span>
<span class="line"><span>BBCOBP</span></span></code></pre></div><p>Eight colours, three elevators (one feeding the exit row), five regular stages and an 8-part boss: <strong>Void Leviathan</strong> (mantis). Random tapping never won in 2,000 tries; the solver finds a winning order.</p><h2 id="hp-tuning" tabindex="-1">4.4 Flight-zone HP tuning <a class="header-anchor" href="#hp-tuning" aria-label="Permalink to &quot;4.4 Flight-zone HP tuning {#hp-tuning}&quot;">​</a></h2><blockquote><p>Enemy fire and zone HP are switched off for now; these numbers apply once they&#39;re back on.</p></blockquote><p>Measured on level 5 by a script that plays the solver&#39;s tap order. The numbers below were taken at zone HP 1140, before the +500 bonus (10 HP per enemy bullet):</p><table tabindex="0"><thead><tr><th>Player model</th><th>Time</th><th>Enemy bullets landed</th><th>Zone HP left</th></tr></thead><tbody><tr><td>Taps the next fighter the moment a slot is free</td><td>53 s</td><td>59</td><td>~48% (now ~64% of 1640)</td></tr><tr><td>Waits for every volley to finish before each tap</td><td>111 s</td><td>256</td><td>0%: destroyed after ~114 hits (now ~164)</td></tr></tbody></table><p>A real player sits between the two. Level 5 has a <code>zoneHpBonus</code> of 500 on top of the formula to give players more room. To make a level more forgiving, raise its <code>hpPerEnemy</code> or add a <code>zoneHpBonus</code>; to change all levels at once, change <code>enemyBulletDamage</code> in <code>src/game/rules.ts</code>.</p><h2 id="_4-5-making-a-level" tabindex="-1">4.5 Making a level <a class="header-anchor" href="#_4-5-making-a-level" aria-label="Permalink to &quot;4.5 Making a level&quot;">​</a></h2><p>See the developer guide&#39;s <a href="./../guide/level-design">Level design</a> page for the JSON format and workflow.</p>`,51))])}const B=r(h,[["render",g]]);export{k as __pageData,B as default};
